import {readFileSync,readdirSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {parse} from '@babel/parser';
const sha=b=>createHash('sha256').update(b).digest('hex');
const root='projects/ai-proxy',base='/tmp/ai-proxy-navigation-polish-before';
const ignored=new Set(['start','end','loc','extra','comments','leadingComments','trailingComments','innerComments']);
const normalized=x=>Array.isArray(x)?x.map(normalized):x&&typeof x==='object'?Object.fromEntries(Object.entries(x).filter(([k])=>!ignored.has(k)).map(([k,v])=>[k,normalized(v)])):x;
const walk=(x,fn)=>{if(!x||typeof x!=='object')return;fn(x);for(const [k,v]of Object.entries(x)){if(ignored.has(k))continue;if(Array.isArray(v))v.forEach(n=>walk(n,fn));else if(v&&typeof v==='object')walk(v,fn);}};
const parseFile=p=>parse(readFileSync(p,'utf8'),{sourceType:'module',plugins:['jsx','typescript']});
const reports=[];
for(const file of ['Settings.tsx','QuickPanel.tsx']){
 const after=parseFile(root+'/src/'+file),before=parseFile(base+'/src/'+file);
 const functions=tree=>{const m=new Map();walk(tree,n=>{if(n.type==='FunctionDeclaration'&&n.id&&n.id.name!=='App'&&n.id.name!=='SideIcon')m.set(n.id.name,JSON.stringify(normalized(n)));});return m;};
 const old=functions(before),now=functions(after);
 const changed=[...new Set([...old.keys(),...now.keys()])].filter(n=>old.get(n)!==now.get(n));
 const patterns=tree=>{const rows=[];walk(tree,n=>{
  if(n.type==='CallExpression'&&n.callee?.object?.name==='console'&&n.callee?.property?.name==='log')rows.push({kind:'console.log',line:n.loc.start.line});
  if(n.type==='CatchClause'&&n.body.body.length===0)rows.push({kind:'empty-catch',line:n.loc.start.line});
  if(n.type==='VariableDeclarator'&&/^(api_?key|secret|access_?token|password)$/i.test(n.id?.name??'')&&n.init?.type==='StringLiteral'&&n.init.value)rows.push({kind:'hardcoded-secret-candidate',line:n.loc.start.line});
  if(n.type==='JSXAttribute'&&n.name?.name==='dangerouslySetInnerHTML')rows.push({kind:'raw-html',line:n.loc.start.line});
 });return rows;};
 reports.push({file:'src/'+file,unchangedNamedBehaviorFunctions:[...now.keys()].filter(n=>old.has(n)&&old.get(n)===now.get(n)),changedNamedBehaviorFunctions:changed,baselinePatterns:patterns(before),currentPatterns:patterns(after)});
 if(changed.length)throw Error('Unexpected handler change');
}
const locales=['en','zh-CN','zh-TW'].map(locale=>({locale,catalog:JSON.parse(readFileSync(root+'/src/i18n/locales/'+locale+'.json','utf8'))}));
const keys=Object.keys(locales[0].catalog).sort();
for(const {locale,catalog}of locales){
 if(JSON.stringify(Object.keys(catalog).sort())!==JSON.stringify(keys))throw Error('Locale key mismatch '+locale);
 for(const k of ['editNamedRule','deleteNamedRule'])if((catalog[k].match(/\{domain\}/g)||[]).length!==1)throw Error('Placeholder mismatch '+locale);
}
console.log(JSON.stringify({status:'PASS',diagnosticsKind:'Babel TSX AST + JSON consistency; NOT semantic TypeScript/LSP',ast:reports,locales:locales.map(({locale,catalog})=>({locale,keyCount:Object.keys(catalog).length,newLabels:['editNamedRule','deleteNamedRule','apRulesListSource'].map(key=>({key,value:catalog[key]}))}))},null,2));
